head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.tmpUpDepNm = "";
scwin.tmpUpDepCd = "";
scwin.tmpDepNm = "";
scwin.tmpDepCd = "";
scwin.tmpChrgIndNm = "";
scwin.tmpDutyGrpTpCd = "";
scwin.tmpSndlocTpCd = "";
scwin.tmpKclicUsrTpId = "";
scwin.logicTp = "0"; // 0:신규, 1:수정, 2:삭제
scwin.isExistDepInfo = false;
scwin.usrPosition = 1; // 트랜젝션 후에 사용자리스트를 리로드 하고 선택 위치를 이동 시키기 위해
scwin.position = 1; // 사용자포지션
scwin.isSameDept = true;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox_01(panel_5);
        scwin.setDefault();
        await scwin.setDataSet();
        await scwin.getDataSetData();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT40020.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name imgDelDate_onclick
 * @description imgDelDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.imgDelDate_onclick = function() {
    try {
        popUpCalendar(tboxAskDate, 'meAskDate', 'yyyymmdd');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40020.imgDelDate_onclick" });
    }
};

/**
 * @method
 * @name mdsDepLst_OnLoadCompleted
 * @description mdsDepLst 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.mdsDepLst_OnLoadCompleted = function(rowcount) {
    try {
        mdsDepLst.setRowPosition(scwin.usrPosition, 0);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40020.mdsDepLst_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name mgPdept_OnClick
 * @description mgPdept 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.mgPdept_OnClick = function(row, colid) {
    try {
        scwin.schMyDept(1, row);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40020.mgPdept_OnClick" });
    }
};

/**
 * @method
 * @name mgPdept_OnKeyPress
 * @description mg Pdept On Key Press 처리
 * @param {*} keycode keycode
 * @returns {void}
 * @hidden N
 */
scwin.mgPdept_OnKeyPress = function(keycode) {
    try {
        if (keycode === '13') {
            tbAuthSch.style.display = "";
            tbAuthSch.focus();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40020.mgPdept_OnKeyPress" });
    }
};

/**
 * @method
 * @name mdsPdept_OnLoadCompleted
 * @description mdsPdept 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.mdsPdept_OnLoadCompleted = function(rowcount) {

};

/**
 * @method
 * @name btnNew_onclick
 * @description 「①신규등록」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btnNew_onclick = function() {
    try {
        if (confirm("동급부서로 등록하려면 '예', 하위부서로 등록하려면 '취소'를 선택하세요.")) {
            scwin.isSameDept = true;
        } else {
            scwin.isSameDept = false;
        }
        scwin.setDeptInfo("0");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40020.btnNew_onclick" });
    }
};

/**
 * @method
 * @name btnModify_onclick
 * @description 「②수정」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btnModify_onclick = function() {
    try {
        scwin.setDeptInfo("1");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40020.btnModify_onclick" });
    }
};

/**
 * @method
 * @name btnDelete_onclick
 * @description 「③삭제」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btnDelete_onclick = function() {
    try {
        scwin.setDeptInfo("2");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40020.btnDelete_onclick" });
    }
};

/**
 * @method
 * @name btnAddSave_onclick
 * @description 「④저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btnAddSave_onclick = async function() {
    try {
        const dep_cd = txtDeptCd.getValue();
        if (scwin.logicTp === '') {
            await $c.win.alert("①, ②, ③ 중 하나의 기능을 먼저 클릭해야 합니다.");
        }
        if (dep_cd === '') {
            await $c.win.alert("부서코드는 필수 입니다.");
            txtDeptCd.focus();
        } else {
            if (scwin.logicTp === '2') {
                await scwin.checkMemberExist();
            } else {
                await scwin.doDepSave();
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT40020.btnAddSave_onclick" });
    }
};

/**
 * @method
 * @name trSave_OnSuccess
 * @description tr Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trSave_OnSuccess = async function() {
    try {
        await $c.win.alert('처리완료');
        scwin.resetList();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT40020.trSave_OnSuccess" });
    }
};

/**
 * @method
 * @name trSave_OnFail
 * @description tr Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trSave_OnFail = async function() {
    try {
        await $c.win.alert('trSave.OnFail()');
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT40020.trSave_OnFail" });
    }
};

/**
 * @method
 * @name tbSch_onkeydown
 * @description tbSch 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.tbSch_onkeydown = function() {
    try {
        if (window.event.keyCode === 13) {
            if (!scwin.isExistDepInfo) {
                scwin.position = 1;
            }
            scwin.schDept(tbSch.getValue());
        } else {
            positon = 1;
            scwin.isExistDepInfo = false;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40020.tbSch_onkeydown" });
    }
};

/**
 * @method
 * @name txtDeptCd_onblur
 * @description txtDeptCd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txtDeptCd_onblur = function() {
    try {
        txtChrgIndNm.setValue(txtDeptCd.getValue());
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40020.txtDeptCd_onblur" });
    }
};

/**
 * @method
 * @name mdsDepHist_OnLoadCompleted
 * @description mdsDepHist 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.mdsDepHist_OnLoadCompleted = function(rowcount) {

};

/**
 * @method
 * @name txtSrchDepHist_onkeydown
 * @description txtSrchDepHist 키 입력 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txtSrchDepHist_onkeydown = async function() {
    try {
        if (window.event.keyCode === 13) await scwin.getDepHistLst(txtSrchDepHist.getValue());
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT40020.txtSrchDepHist_onkeydown" });
    }
};

/**
 * @method
 * @name mdsDepLst_OnRowPosChanged
 * @description mds Dep Lst On Row Pos Changed 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.mdsDepLst_OnRowPosChanged = function(row) {
    try {
        scwin.tmpUpDepNm = mdsDepLst.getCellData(row, "UP_DEP_NM");
        scwin.tmpUpDepCd = mdsDepLst.getCellData(row, "UP_DEP_CD");
        scwin.tmpDepNm = mdsDepLst.getCellData(row, "DEP_NM");
        scwin.tmpDepCd = mdsDepLst.getCellData(row, "DEP_CD");
        scwin.tmpChrgIndNm = mdsDepLst.getCellData(row, "CHRG_IND_NM");
        scwin.tmpDutyGrpTpCd = mdsDepLst.getCellData(row, "DUTY_GRP_TP_CD");
        scwin.tmpSndlocTpCd = mdsDepLst.getCellData(row, "SNDLOC_TP_CD");
        scwin.tmpKclicUsrTpId = mdsDepLst.getCellData(row, "KCLIC_USR_TP_ID");
        scwin.clearEditTextBox();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40020.mdsDepLst_OnRowPosChanged" });
    }
};

/**
 * @method
 * @name img_1_onclick
 * @description 「고침」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_1_onclick = function() {
    try {
        mdsDepLst.reset();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40020.img_1_onclick" });
    }
};

/**
 * @method
 * @name btnHistSave_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btnHistSave_onclick = function() {
    try {
        scwin.doHistSave();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40020.btnHistSave_onclick" });
    }
};

/**
 * @method
 * @name mxmGusrLst_OnLButtonDown
 * @description mxm Gusr Lst On LButton Down 처리
 * @param {*} type type
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @param {*} x x
 * @param {*} y y
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.mxmGusrLst_OnLButtonDown = async function(type, row, colid, x, y) {
    try {
        scwin.usrPosition = row;
        await scwin.getDepHistLst(scwin.tmpDepCd);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT40020.mxmGusrLst_OnLButtonDown" });
    }
};

/**
 * @method
 * @name mgDepHist_onlbuttondown
 * @description mgDepHist onlbuttondown 이벤트
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @param {*} xpos xpos
 * @param {*} ypos ypos
 * @returns {void}
 * @hidden N
 */
scwin.mgDepHist_onlbuttondown = function(row, colid, xpos, ypos) {
    try {
        scwin.schMyDept(2, row);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40020.mgDepHist_onlbuttondown" });
    }
};

/**
 * @method
 * @name txtUpDeptCd_onkeyup
 * @description txtUpDeptCd 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txtUpDeptCd_onkeyup = function() {
    try {
        const ver = txtUpDeptCd.getValue();
        let deptCd = '';
        if (ver.length === 4) {
            for (let i = 1; i <= mdsDepLst.getRowCount(); i++) {
                deptCd = mdsDepLst.getCellData(i, "DEP_CD");
                if (ver === deptCd) {
                    txtUpDeptNm.setValue(mdsDepLst.getCellData(i, "DEP_NM"));
                    break;
                }
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40020.txtUpDeptCd_onkeyup" });
    }
};

/**
 * @method
 * @name mdsMemberCheck_OnLoadCompleted
 * @description mdsMemberCheck 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.mdsMemberCheck_OnLoadCompleted = async function(rowcount) {
    try {
        let cnt = 0;
        if (rowcount !== 0) {
            cnt = mdsMemberCheck.getCellData(1, "COUNT");
            if (cnt !== 0) {
                await $c.win.alert("팀원이 있는 팀은 삭제 할 수 없습니다.");
            } else {
                await scwin.doDepSave();
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT40020.mdsMemberCheck_OnLoadCompleted" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
