 * @description get Data Set Data 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getDataSetData = async function() {
    const sbmOptions = {
        id : "sbm_mdsPdept",
        action : "/depusr.do",
        ref : "",
        target : "mdsPdept=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_mdsDepLst",
        action : "/depusr.do",
        ref : "",
        target : "mdsDepLst=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

