///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name schMyDept
 * @description tp 1:상위부서 목록 2:히스토리
 * @param {*} tp tp
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.schMyDept = function(tp, row) {
    let vDept = '';
    if (tp === 1) {
        vDept = mdsPdept.getCellData(row, "DEP_CD");
    } else {
        vDept = mdsDepHist.getCellData(row, "DEP_CD");
    }
    let tmpVal1;
    for (let i = 0; i <= mdsDepLst.getRowCount(); i++) {
        tmpVal1 = mdsDepLst.getCellData(i, "DEP_CD");
        if (tmpVal1 === vDept) {
            mdsDepLst.setRowPosition(i, 0);
        }
    }
};

/**
 * @method
 * @name schDept
 * @description sch Dept 처리
 * @param {*} ver ver
 * @returns {void}
 * @hidden N
 */
scwin.schDept = function(ver) {
    let tmpVal1;
    let tmpVal2;
};

/**
 * @method
 * @name setDeptInfo
 * @description ver 0:신규, 1:수정, 2:삭제
 * @param {*} ver ver
 * @returns {void}
 * @hidden N
 */
scwin.setDeptInfo = function(ver) {
    scwin.logicTp = ver;
    if (ver === "0") {
        lblStrtDD.style.display = "";
        lblEndDD.style.display = "none";
        if (scwin.isSameDept) {
            txtUpDeptNm.setValue(scwin.tmpUpDepNm);
            txtUpDeptCd.setValue(scwin.tmpUpDepCd);
        } else {
            txtUpDeptNm.setValue(scwin.tmpDepNm);
            txtUpDeptCd.setValue(scwin.tmpDepCd);
        }
        txtChrgIndNm.setValue("");
        txtDutyGrpTpCd.setValue(scwin.tmpDutyGrpTpCd);
        txtSndlocTpCd.setValue(scwin.tmpSndlocTpCd);
        txtKclicUsrTpId.setValue(scwin.tmpKclicUsrTpId);
        txtUpDeptNm.setReadOnly(true);
        txtUpDeptCd.setReadOnly(true);
        txtDeptNm.setReadOnly(false);
        txtDeptCd.setReadOnly(false);
        txtDeptNm.setValue("");
        txtDeptCd.setValue("");
    } else if (ver === 1) {
        lblStrtDD.style.display = "";
        lblEndDD.style.display = "none";
        txtUpDeptNm.setValue(scwin.tmpUpDepNm);
        txtUpDeptCd.setValue(scwin.tmpUpDepCd);
        txtDeptNm.setValue(scwin.tmpDepNm);
        txtDeptCd.setValue(scwin.tmpDepCd);
        txtChrgIndNm.setValue(scwin.tmpChrgIndNm);
        txtDutyGrpTpCd.setValue(scwin.tmpDutyGrpTpCd);
        txtSndlocTpCd.setValue(scwin.tmpSndlocTpCd);
        txtKclicUsrTpId.setValue(scwin.tmpKclicUsrTpId);
        txtUpDeptNm.setReadOnly(true);
        txtUpDeptCd.setReadOnly(false);
        txtDeptNm.setReadOnly(false);
        txtDeptCd.setReadOnly(false);
    } else {
        lblStrtDD.style.display = "none";
        lblEndDD.style.display = "";
        txtUpDeptNm.setValue(scwin.tmpUpDepNm);
        txtUpDeptCd.setValue(scwin.tmpUpDepCd);
        txtDeptNm.setValue(scwin.tmpDepNm);
        txtDeptCd.setValue(scwin.tmpDepCd);
        txtChrgIndNm.setValue(scwin.tmpChrgIndNm);
        txtDutyGrpTpCd.setValue(scwin.tmpDutyGrpTpCd);
        txtSndlocTpCd.setValue(scwin.tmpSndlocTpCd);
        txtKclicUsrTpId.setValue(scwin.tmpKclicUsrTpId);
        txtUpDeptNm.setReadOnly(true);
        txtUpDeptCd.setReadOnly(true);
        txtDeptNm.setReadOnly(true);
        txtDeptCd.setReadOnly(true);
    }
};

/**
 * @method
 * @name setDefault
 * @description set Default 처리
 * @returns {void}
 * @hidden N
 */
scwin.setDefault = function() {
    lblEndDD.style.display = "none";
};

/**
 * @method
 * @name doDepSave
 * @description do Dep Save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.doDepSave = async function() {
    if (await scwin.valueCheck()) {
        if (await scwin.setSaveDeptInfo()) {
            if (scwin.logicNdeptCheck()) {
                let url = "/depusr.do?method=saveDeptInfo";
                let keyVal = "JSP(I:pInput=mdsDeptSave)";
                trSave.Action = url;
                trSave.KeyName = "toinb_dataid4";
                trSave.KeyValue = keyVal;
                trSave.post();
            }
        } else {
            await $c.win.alert('팀 정보 세팅 오류!');
        }
    }
};

/**
 * @method
 * @name doHistSave
 * @description do Hist Save 처리
 * @returns {void}
 * @hidden N
 */
scwin.doHistSave = function() {
    let msg1 = "수정된 사항을 저장하시겠습니까?";
    const msg2 = "\r\n(체크된 Row는 수정과 상관 없이 삭제 됩니다.)";
    if (scwin.isHistChecked()) msg1 = msg1 + msg2;
    if (confirm(msg1)) {
        if (scwin.doDeleteHist()) {
            let url = "/depusr.do?method=saveHistInfo";
            let keyVal = "JSP(I:pInput=mdsDepHist)";
            trSave.Action = url;
            trSave.KeyName = "toinb_dataid4";
            trSave.KeyValue = keyVal;
            trSave.post();
        }
    }
};

/**
 * @method
 * @name doDeleteHist
 * @description 순서대로 지우면 하나가 지워지면서 밑엣게 위로 올라옴. 그래서 거꾸로 지움
 * @returns {void}
 * @hidden N
 */
scwin.doDeleteHist = function() {
    for (i = mdsDepHist.getRowCount(); i >= 1; i--) {
        if (mdsDepHist.getCellData(i, "CHK_FLAG") === 1) {
            mdsDepHist.removeRow(i);
        }
    }
    return true;
};

/**
 * @method
 * @name isHistChecked
 * @description is Hist Checked 처리
 * @returns {void}
 * @hidden N
 */
scwin.isHistChecked = function() {
    const isChecked = false;
    return isChecked;
};

/**
 * @method
 * @name logicNdeptCheck
 * @description logic Ndept Check 처리
 * @returns {void}
 * @hidden N
 */
scwin.logicNdeptCheck = function() {
    if (scwin.logicTp === "0") {
        if (confirm(txtDeptNm.getValue() + "(" + txtDeptCd.getValue() + ")를 신규생성 하시겠습니까?")) {
            return true;
        } else return false;
    } else if (scwin.logicTp === "1") {
        const old_dep_cd = mdsDeptSave.getCellData(1, "DEP_CD");
        const new_dep_cd = mdsDeptSave.getCellData(1, "NEW_DEP_CD");
        if (old_dep_cd !== new_dep_cd) {
            if (confirm('팀코드가 변경되었습니다. 계속진행하시겠습니까?')) {

            } else {
                return false;
            }
        }
        let msg = "[" + scwin.tmpDepNm + "(" + scwin.tmpDepCd + ")]에서 [" + txtDeptNm.getValue() + "](으)로 변경 하시겠습니까?";
        if (scwin.tmpDepNm === txtDeptNm.getValue()) {
            msg = scwin.tmpDepNm + "(" + scwin.tmpDepCd + ") 정보를 변경 하시겠습니까?";
        }
        if (confirm(msg)) {
            return true;
        } else return false;
    } else if (scwin.logicTp === "2") {
        if (confirm(scwin.tmpDepNm + "(" + scwin.tmpDepCd + ")를 삭제 하시겠습니까?")) {
            return true;
        } else return false;
    }
};

/**
 * @method
 * @name valueCheck
 * @description value Check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.valueCheck = async function() {
    if (meAskDate.getValue() === "") {
        await $c.win.alert("[시작일/종료일]은 필수입니다.");
        return false;
    }
    if (scwin.tmpDepCd === "" || scwin.tmpDepNm === "") {
        await $c.win.alert("팀코드와 팀명은 필수입니다.");
        return false;
    }
    return true;
};

/**
 * @method
 * @name setSaveDeptInfo
 * @description set Save Dept Info 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setSaveDeptInfo = async function() {
    try {
        if (mdsDeptSave.getRowCount() !== 0) {
            mdsDeptSave.removeAll();
        }
        mdsDeptSave.insertRow();
        mdsDeptSave.setCellData(1, "DEP_CD", scwin.tmpDepCd);
        mdsDeptSave.setCellData(1, "NEW_DEP_CD", txtDeptCd.getValue());
        mdsDeptSave.setCellData(1, "UP_DEP_CD", txtUpDeptCd.getValue());
        mdsDeptSave.setCellData(1, "DEP_NM", txtDeptNm.getValue());
        mdsDeptSave.setCellData(1, "CHRG_IND_NM", txtChrgIndNm.getValue());
        mdsDeptSave.setCellData(1, "REMK", txtRemk.Text);
        mdsDeptSave.setCellData(1, "DUTY_GRP_TP_CD", txtDutyGrpTpCd.getValue());
        mdsDeptSave.setCellData(1, "SNDLOC_TP_CD", txtSndlocTpCd.getValue());
        mdsDeptSave.setCellData(1, "KCLIC_USR_TP_ID", txtKclicUsrTpId.getValue());
        mdsDeptSave.setCellData(1, "ASK_DATE", meAskDate.getValue());
        mdsDeptSave.setCellData(1, "LOGIC_TP", scwin.logicTp);
        return true;
    } catch (err) {
        await $c.win.alert(err);
        return false;
    }
};

